-- MySQL Server 8+; run in MySQL Workbench
CREATE DATABASE IF NOT EXISTS saudi_ecommerce CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE saudi_ecommerce;
CREATE TABLE IF NOT EXISTS customers (customer_id INT PRIMARY KEY, city VARCHAR(80) NOT NULL, region VARCHAR(80) NOT NULL, signup_date DATE NOT NULL, customer_segment VARCHAR(30) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS products (product_id INT PRIMARY KEY, category VARCHAR(80) NOT NULL, subcategory VARCHAR(100) NOT NULL, unit_price_sar DECIMAL(12,2) NOT NULL, unit_cost_sar DECIMAL(12,2) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS orders (order_id INT PRIMARY KEY, customer_id INT NOT NULL, order_date DATE NOT NULL, order_status VARCHAR(25) NOT NULL, payment_method VARCHAR(40) NOT NULL, channel VARCHAR(40) NOT NULL, discount_sar DECIMAL(12,2) NOT NULL, shipping_fee_sar DECIMAL(12,2) NOT NULL, order_total_sar DECIMAL(14,2) NOT NULL, CONSTRAINT fk_orders_customers FOREIGN KEY (customer_id) REFERENCES customers(customer_id), INDEX ix_orders_date (order_date), INDEX ix_orders_status_date (order_status,order_date), INDEX ix_orders_customer_date (customer_id,order_date)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_items (order_item_id INT PRIMARY KEY, order_id INT NOT NULL, product_id INT NOT NULL, quantity INT NOT NULL, unit_price_sar DECIMAL(12,2) NOT NULL, unit_cost_sar DECIMAL(12,2) NOT NULL, line_revenue_sar DECIMAL(14,2) NOT NULL, CONSTRAINT fk_items_orders FOREIGN KEY (order_id) REFERENCES orders(order_id), CONSTRAINT fk_items_products FOREIGN KEY (product_id) REFERENCES products(product_id), INDEX ix_items_order (order_id), INDEX ix_items_product (product_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS deliveries (delivery_id INT PRIMARY KEY, order_id INT NOT NULL UNIQUE, delivery_partner VARCHAR(50) NOT NULL, warehouse_city VARCHAR(80) NOT NULL, promised_days INT NOT NULL, actual_days INT NULL, delivery_status VARCHAR(25) NOT NULL, delivery_cost_sar DECIMAL(12,2) NOT NULL, customer_rating INT NULL, CONSTRAINT fk_deliveries_orders FOREIGN KEY (order_id) REFERENCES orders(order_id), INDEX ix_delivery_partner_status (delivery_partner,delivery_status)) ENGINE=InnoDB;
